  // The `Dispatch ... and watch` step of a dispatching leg, run text only.
  String dispatchStepRun(String leg) {
    final steps =
        jobsOf('.github/workflows/daily-publish.yml')[leg]['steps']
            as YamlList;
    final step =
        steps.firstWhere(
              (s) =>
                  s is YamlMap &&
