                  s is YamlMap &&
                  s['uses'].toString().startsWith('actions/checkout'),
            ),
            isTrue,
            reason:
                'leg "$leg" must check out the repo to run scripts/dispatch_and_watch.sh',
          );
        }
      },
    );
  });
